import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.4yUrvjMt.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),d={name:"changelog.md"};function l(c,e,i,n,s,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Pravaha are documented here. Pravaha follows <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><hr><h2 id="v0-1-0-—-2025-05-01" tabindex="-1">v0.1.0 — 2025-05-01 <a class="header-anchor" href="#v0-1-0-—-2025-05-01" aria-label="Permalink to &quot;v0.1.0 — 2025-05-01&quot;">​</a></h2><p>Initial public release. 🎉</p><h3 id="packages-released" tabindex="-1">Packages Released <a class="header-anchor" href="#packages-released" aria-label="Permalink to &quot;Packages Released&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Package</th><th>Version</th></tr></thead><tbody><tr><td><code>@pravaha/core</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/adapter-claude</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/adapter-openai</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/adapter-ollama</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/adapter-claude-vertex</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/adapter-trace-fs</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/adapter-memory-redis</code></td><td><code>0.1.0</code></td></tr><tr><td><code>@pravaha/cli</code></td><td><code>0.1.0</code></td></tr><tr><td><code>create-pravaha-app</code></td><td><code>0.1.0</code></td></tr></tbody></table><h3 id="core-pravaha-core" tabindex="-1">Core (<code>@pravaha/core</code>) <a class="header-anchor" href="#core-pravaha-core" aria-label="Permalink to &quot;Core (`@pravaha/core`)&quot;">​</a></h3><p><strong>Pipeline primitives</strong></p><ul><li><code>PipelineBuilder</code> — fluent API for assembling multi-step pipelines with full TypeScript inference</li><li><code>Pipeline.run()</code> — execute a pipeline end-to-end, returning typed <code>PipelineResult</code></li><li><code>Pipeline.dryRun()</code> — execute with mock responses for testing and CI validation</li><li><code>ExecutionContext</code> — immutable context carrying run ID, pipeline metadata, memory, and plugins</li></ul><p><strong>Step types</strong></p><ul><li><code>BaseStep&lt;TInput, TOutput&gt;</code> — abstract base class for all steps</li><li><code>TransformStep</code> — inline data transformation with a synchronous or async function</li><li><code>ToolStep</code> / <code>defineToolStep</code> — strongly typed tool invocations with Zod schema validation</li><li><code>AgentStep</code> — LLM agent with tool-calling loop, pluggable via <code>ToolCallingAdapter</code></li><li><code>defineAgentOutputParser</code> — parse structured JSON or regex output from agent responses</li></ul><p><strong>Routing</strong></p><ul><li><code>LinearRouter</code> — routes to a fixed next step or ends the pipeline</li><li><code>ConditionalRouter</code> — routes based on step output with an ordered list of conditions and a fallback</li></ul><p><strong>Observability</strong></p><ul><li><code>Trace</code> / <code>TraceEvent</code> — automatic per-step tracing with timing and routing decisions</li><li><code>TraceStore</code> interface — pluggable trace persistence</li><li><code>InMemoryTraceStore</code> — default in-process store</li></ul><p><strong>Memory</strong></p><ul><li><code>MemoryStore</code> interface — key-value store for cross-run persistence</li><li><code>InMemoryStore</code> — default in-process implementation</li></ul><p><strong>Resilience</strong></p><ul><li><code>withRetry()</code> — wraps any step with exponential backoff retry logic</li><li><code>RetryPolicy</code> — configure <code>maxAttempts</code>, <code>backoffMs</code>, <code>retryOn</code> error types</li></ul><p><strong>Error hierarchy</strong></p><ul><li><code>PravahaError</code> — base class</li><li><code>ValidationError</code>, <code>StepExecutionError</code>, <code>PipelineConfigError</code>, <code>RouterError</code></li><li><code>LLMRateLimitError</code>, <code>LLMTimeoutError</code>, <code>LLMInvalidResponseError</code></li><li><code>AgentMaxIterationsError</code>, <code>AgentToolCallError</code></li></ul><p><strong>Plugins</strong></p><ul><li><code>PravahaPlugin</code> interface — lifecycle hooks: <code>onPipelineStart</code>, <code>onStepStart</code>, <code>onStepComplete</code>, <code>onPipelineComplete</code>, <code>onError</code></li><li><code>PluginRegistry</code> — manages ordered plugin execution</li></ul><p><strong>Streaming</strong></p><ul><li><code>BaseStreamingStep&lt;TInput, TOutput&gt;</code> — base class for streaming-capable steps</li><li><code>StreamChunk</code> type — <code>delta</code>, <code>accumulated</code>, <code>index</code></li></ul><h3 id="adapters" tabindex="-1">Adapters <a class="header-anchor" href="#adapters" aria-label="Permalink to &quot;Adapters&quot;">​</a></h3><p><strong><code>@pravaha/adapter-claude</code></strong></p><ul><li><code>ClaudeLLMStep</code> — standard (non-streaming) Claude completion</li><li><code>ClaudeStreamingLLMStep</code> — streaming Claude completion with <code>stream()</code> async iterator</li><li><code>ClaudeToolCallingAdapter</code> — native <code>tool_use</code> content blocks for <code>AgentStep</code></li></ul><p><strong><code>@pravaha/adapter-openai</code></strong></p><ul><li><code>OpenAILLMStep</code> — standard GPT completion</li><li><code>OpenAIStreamingLLMStep</code> — streaming GPT completion</li><li><code>OpenAIToolCallingAdapter</code> — native <code>tool_calls</code> format for <code>AgentStep</code>; Azure OpenAI supported via <code>baseURL</code></li></ul><p><strong><code>@pravaha/adapter-ollama</code></strong></p><ul><li><code>OllamaLLMStep</code> — local Ollama completion with <code>healthCheck()</code> method</li><li><code>OllamaStreamingLLMStep</code> — streaming local completion</li><li><code>OllamaToolCallingAdapter</code> — JSON-mode tool calling for local models (llama3.1, mistral-nemo recommended)</li></ul><p><strong><code>@pravaha/adapter-claude-vertex</code></strong></p><ul><li><code>ClaudeVertexLLMStep</code> — Claude on Google Cloud Vertex AI</li><li><code>ClaudeVertexToolCallingAdapter</code> — tool calling via Vertex AI; supports workload identity federation</li></ul><p><strong><code>@pravaha/adapter-trace-fs</code></strong></p><ul><li><code>FsTraceStore</code> — writes trace files to <code>.pravaha/traces/</code> for use with the CLI</li></ul><p><strong><code>@pravaha/adapter-memory-redis</code></strong></p><ul><li><code>RedisMemoryStore</code> — Redis-backed <code>MemoryStore</code> for persistent cross-run memory</li></ul><h3 id="cli-pravaha-cli" tabindex="-1">CLI (<code>@pravaha/cli</code>) <a class="header-anchor" href="#cli-pravaha-cli" aria-label="Permalink to &quot;CLI (`@pravaha/cli`)&quot;">​</a></h3><ul><li><code>pravaha trace list</code> — list all saved traces ordered most recent first</li><li><code>pravaha trace show &lt;runId&gt;</code> — print a full trace to the terminal</li><li><code>pravaha serve</code> — start the visual trace viewer at <code>http://localhost:4321</code></li><li><code>pravaha export &lt;runId&gt;</code> — export a trace to JSON or CSV</li></ul><h3 id="scaffolding-create-pravaha-app" tabindex="-1">Scaffolding (<code>create-pravaha-app</code>) <a class="header-anchor" href="#scaffolding-create-pravaha-app" aria-label="Permalink to &quot;Scaffolding (`create-pravaha-app`)&quot;">​</a></h3><ul><li><code>pnpm create pravaha-app</code> — interactive project scaffold</li><li>Templates: <code>basic</code>, <code>agent</code>, <code>streaming</code></li><li>Generates a fully configured TypeScript project with the selected template</li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><ul><li><code>support-ticket-triage</code> — flagship example demonstrating rule-based routing, KB lookup ToolStep, AgentStep triage, dry-run, and production adaptation guide</li></ul><hr><h2 id="versioning-policy" tabindex="-1">Versioning Policy <a class="header-anchor" href="#versioning-policy" aria-label="Permalink to &quot;Versioning Policy&quot;">​</a></h2><p>Pravaha follows <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>:</p><ul><li><strong>Patch</strong> (<code>0.1.x</code>) — bug fixes and documentation updates</li><li><strong>Minor</strong> (<code>0.x.0</code>) — new features, backwards-compatible</li><li><strong>Major</strong> (<code>x.0.0</code>) — breaking changes; migration guide provided</li></ul><p>Breaking changes are called out explicitly in the changelog entry with a <strong>Breaking:</strong> label and a migration path.</p><hr><h2 id="stay-updated" tabindex="-1">Stay Updated <a class="header-anchor" href="#stay-updated" aria-label="Permalink to &quot;Stay Updated&quot;">​</a></h2><ul><li><strong>GitHub Releases</strong> — each release has a tagged GitHub release with full notes</li><li><strong>npm</strong> — all packages publish to the <code>@pravaha</code> scope on npm</li><li><strong>Discussions</strong> — <a href="https://github.com/pravaham/pravaha/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> for questions and feedback</li></ul>',53)])])}const h=o(d,[["render",l]]);export{g as __pageData,h as default};
